CREATE TABLE room_event (event_id UUID PRIMARY KEY DEFAULT uuid_v7(),room_id UUID NOT NULL,sequence BIGINT NOT NULL,event_type VARCHAR(128) NOT NULL,actor_id UUID NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),payload TEXT,state_version BIGINT NOT NULL,FOREIGN KEY(room_id) REFERENCES room(id),UNIQUE(room_id,sequence)); CREATE INDEX idx_room_event_replay ON room_event(room_id,sequence);
